/// `AtomicMachine::Atomic<T>`
fn atomic<T: AtomicTexel>(context: &Context, vao: GLuint, stage: i32, internalformat: GLenum) -> bool {
    let gl = context.gl();
    let program = stage_program(gl, stage, &gen_atomic_shader::<T>(stage, internalformat));

    let mut texture_result: GLuint = 0;
    gl!(gl.gen_textures(1, &mut texture_result));
    gl!(gl.bind_texture(glw::GL_TEXTURE_2D, texture_result));
    set_nearest(gl, glw::GL_TEXTURE_2D);
    gl!(gl.tex_storage_2d(glw::GL_TEXTURE_2D, 1, glw::GL_RGBA32F, 1, 1));

    let targets: [GLenum; 7] = [
        glw::GL_TEXTURE_2D,
        glw::GL_TEXTURE_3D,
        glw::GL_TEXTURE_RECTANGLE,
        glw::GL_TEXTURE_CUBE_MAP,
        glw::GL_TEXTURE_BUFFER,
        glw::GL_TEXTURE_1D_ARRAY,
        glw::GL_TEXTURE_2D_ARRAY,
    ];
    let mut textures = [0 as GLuint; 7];
    let mut buffer: GLuint = 0;
    gl!(gl.gen_textures(7, textures.as_mut_ptr()));
    gl!(gl.gen_buffers(1, &mut buffer));
    for (i, &target) in targets.iter().enumerate() {
        gl!(gl.bind_texture(target, textures[i]));
        if target != glw::GL_TEXTURE_BUFFER {
            set_nearest(gl, target);
        }
        match target {
            glw::GL_TEXTURE_2D | glw::GL_TEXTURE_RECTANGLE | glw::GL_TEXTURE_CUBE_MAP => {
                gl!(gl.tex_storage_2d(target, 1, internalformat, 1, 1))
            }
            glw::GL_TEXTURE_3D | glw::GL_TEXTURE_2D_ARRAY => gl!(gl.tex_storage_3d(target, 1, internalformat, 1, 1, 2)),
            glw::GL_TEXTURE_BUFFER => {
                gl!(gl.bind_buffer(glw::GL_TEXTURE_BUFFER, buffer));
                gl!(gl.buffer_data(glw::GL_TEXTURE_BUFFER, 4, std::ptr::null(), glw::GL_DYNAMIC_DRAW));
                gl!(gl.bind_buffer(glw::GL_TEXTURE_BUFFER, 0));
                gl!(gl.tex_buffer(target, internalformat, buffer));
            }
            _ => gl!(gl.tex_storage_2d(target, 1, internalformat, 1, 2)),
        }
    }

    gl!(gl.bind_image_texture(0, texture_result, 0, glw::FALSE, 0, glw::GL_WRITE_ONLY, glw::GL_RGBA32F));
    for (unit, layered) in [
        (1, glw::FALSE),
        (2, glw::TRUE),
        (3, glw::FALSE),
        (4, glw::TRUE),
        (5, glw::FALSE),
        (6, glw::TRUE),
        (7, glw::TRUE),
    ] {
        gl!(gl.bind_image_texture(
            unit,
            textures[unit as usize - 1],
            0,
            layered,
            0,
            glw::GL_READ_WRITE,
            internalformat
        ));
    }
    gl!(gl.use_program(program));
    for (unit, name) in [
        "g_image_result",
        "g_image_2d",
        "g_image_3d",
        "g_image_2drect",
        "g_image_cube",
        "g_image_buffer",
        "g_image_1darray",
        "g_image_2darray",
    ]
    .into_iter()
    .enumerate()
    {
        gl!(gl.uniform_1i(uniform_location(gl, program, name), unit as GLint));
    }
    gl!(gl.bind_vertex_array(vao));
    run_stage_program(gl, stage);

    let mut status = true;
    let mut color = [0.0f32; 4];
    gl!(gl.bind_texture(glw::GL_TEXTURE_2D, texture_result));
    gl!(gl.memory_barrier(glw::GL_TEXTURE_UPDATE_BARRIER_BIT));
    gl!(gl.get_tex_image(
        glw::GL_TEXTURE_2D,
        0,
        glw::GL_RGBA,
        glw::GL_FLOAT,
        color.as_mut_ptr().cast()
    ));
    if color != [0.0, 1.0, 0.0, 1.0] {
        status = false;
        log::info!(
            "Color is: {}. Format is: {}. Stage is: {}",
            vec_to_glsl(&color),
            format_enum_to_string(internalformat),
            stage_name(stage)
        );
    }

    gl!(gl.use_program(0));
    gl!(gl.delete_program(program));
    gl!(gl.delete_textures(7, textures.as_ptr()));
    gl!(gl.delete_textures(1, &texture_result));
    gl!(gl.delete_buffers(1, &buffer));
    status
}

/// The stage cases of `AtomicMachine`.
pub(super) struct AtomicMachine {
    stage: i32,
    vao: GLuint,
}

impl AtomicMachine {
    pub(super) fn new(stage: i32) -> Self {
        Self { stage, vao: 0 }
    }
}

impl Subcase for AtomicMachine {
    fn setup(&mut self, context: &Context) -> SubcaseResult {
        let gl = context.gl();
        gl!(gl.enable(glw::GL_RASTERIZER_DISCARD));
        gl!(gl.gen_vertex_arrays(1, &mut self.vao));
        Ok(NO_ERROR)
    }

    fn run(&mut self, context: &Context) -> SubcaseResult {
        let gl = context.gl();
        if self.stage == 4 && !context.context_info.is_extension_supported("GL_ARB_compute_shader") {
            log::info!("GL_ARB_compute_shader not supported, skipping test");
            return Ok(NO_ERROR);
        }
        if !supported_in_stage(gl, self.stage, 8) {
            return Ok(NOT_SUPPORTED);
        }
        if !atomic::<i32>(context, self.vao, self.stage, glw::GL_R32I) {
            return Ok(ERROR);
        }
        if !atomic::<u32>(context, self.vao, self.stage, glw::GL_R32UI) {
            return Ok(ERROR);
        }
        Ok(NO_ERROR)
    }

    fn cleanup(&mut self, context: &Context) -> SubcaseResult {
        let gl = context.gl();
        gl!(gl.disable(glw::GL_RASTERIZER_DISCARD));
        gl!(gl.delete_vertex_arrays(1, &self.vao));
        Ok(NO_ERROR)
    }
}
